import{_ as o,a0 as l,w as p,s as g,ao as a,I as i,x as n,a1 as r,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"在 Gnome 中共享電腦屏幕 | LCTT x X-CMD","titleTemplate":false,"description":"在 Gnome 中共享電腦屏幕 | LCTT (202202) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Gnome 中共享電腦屏幕 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Gnome 中共享電腦屏幕 | LCTT (202202) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202202/20220128 Sharing the computer screen in Gnome","title":"在 Gnome 中共享電腦屏幕","tag":"202202","desc":""},"relativePath":"202202/20220128 Sharing the computer screen in Gnome.md","filePath":"[post].md"}'),m={name:"202202/20220128 Sharing the computer screen in Gnome.md"};function d(u,t,h,b,f,c){const e=l("Link");return p(),g("div",null,[t[22]||(t[22]=a(`<h1 id="在-gnome-中共享電腦屏幕" tabindex="-1">在 Gnome 中共享電腦屏幕 <a class="header-anchor" href="#在-gnome-中共享電腦屏幕" aria-label="Permalink to “在 Gnome 中共享電腦屏幕”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202202/11/101112soc722i55ut7r6nq.jpg" alt=""></p><p>你不希望別人能夠監視甚至控制你的電腦，你通常會努力使用各種安全機制來切斷任何此類企圖。然而，有時會出現這樣的情況：你迫切需要一個朋友，或一個專家來幫助你解決電腦問題，但他們並不同時在同一地點。你如何向他們展示呢？你應該拿着你的手機，拍下你的屏幕照片，然後發給他們嗎？你應該錄製一個視頻嗎？當然不是。你可以與他們分享你的屏幕，並可能讓他們遠程控制你的電腦一段時間。在這篇文章中，我將介紹如何在 Gnome 中允許共享電腦屏幕。</p><h3 id="設置服務器以共享屏幕" tabindex="-1">設置服務器以共享屏幕 <a class="header-anchor" href="#設置服務器以共享屏幕" aria-label="Permalink to “設置服務器以共享屏幕”">​</a></h3><p><strong>服務器</strong> 是一台提供（服務）一些內容的計算機，其他計算機（<strong>客户端</strong>）將消費這些內容。在本文中，服務器運行的是 <strong>Fedora Workstation</strong> 和標準的 <strong>Gnome 桌面</strong>。</p><h4 id="打開-gnome-屏幕共享" tabindex="-1">打開 Gnome 屏幕共享 <a class="header-anchor" href="#打開-gnome-屏幕共享" aria-label="Permalink to “打開 Gnome 屏幕共享”">​</a></h4><p>默認情況下，Gnome 中共享計算機屏幕的功能是 <strong>關閉</strong> 的。要使用它，你需要把它打開：</p><ol><li>啓動 <ruby>Gnome 控制中心<rt>Gnome Control Center</rt></ruby>。</li><li>點擊 <ruby>共享<rt>Sharing</rt></ruby> 標籤。 <img src="https://fedoramagazine.org/wp-content/uploads/2022/01/settings_sharing_off.png" alt="Sharing switched off"></li><li>用右上角的滑塊打開共享。</li><li>單擊 <ruby>屏幕共享<rt>Screen sharing</rt></ruby>。 <img src="https://fedoramagazine.org/wp-content/uploads/2022/01/settings_sharing_on.png" alt="Sharing switched on"></li><li>用窗口左上角的滑塊打開屏幕共享。</li><li>如果你希望能夠從客户端控制屏幕，請勾選 <ruby>允許連接控制屏幕<rt>Allow connections to control the screen</rt></ruby>。不勾選這個按鈕訪問共享屏幕只允許 <ruby>僅瀏覽<rt>view-only</rt></ruby>。</li><li>如果你想手動確認所有傳入的連接，請選擇 <ruby>新連接必須請求訪問<rt>New connections must ask for access</rt></ruby>。</li><li>如果你想允許知道密碼的人連接（你不會被通知），選擇 <ruby>需要密碼<rt>Require a password</rt></ruby> 並填寫密碼。密碼的長度只能是 8 個字符。</li><li>勾選 <ruby>顯示密碼<rt>Show password</rt></ruby> 以查看當前的密碼是什麼。為了多一點保護，不要在這裏使用你的登錄密碼，而是選擇一個不同的密碼。</li><li>如果你有多個網絡可用，你可以選擇在哪個網絡上訪問該屏幕。</li></ol><h3 id="設置客户端以顯示遠程屏幕" tabindex="-1">設置客户端以顯示遠程屏幕 <a class="header-anchor" href="#設置客户端以顯示遠程屏幕" aria-label="Permalink to “設置客户端以顯示遠程屏幕”">​</a></h3><p><strong>客户端</strong> 是一台連接到由服務器提供的服務（或內容）的計算機。本演示還將在客户端上運行 <strong>Fedora Workstation</strong>，但如果它運行一個 VNC 客户端，操作系統實際上應該不太重要。</p><h4 id="檢查可見性" tabindex="-1">檢查可見性 <a class="header-anchor" href="#檢查可見性" aria-label="Permalink to “檢查可見性”">​</a></h4><p>在 Gnome 中，服務器和客户端之間共享計算機屏幕需要一個有效的網絡連接，以及它們之間可見的“路由”。如果你不能建立這樣的連接，你將無法查看或控制服務器的共享屏幕，這裏描述的整個過程將無法工作。</p><p>為了確保連接的存在，找出服務器的 IP 地址。</p><p>啓動 <ruby>Gnome 控制中心<rt>Gnome Control Center</rt></ruby>，又稱 <ruby>設置<rt>Settings</rt></ruby>。使用右上角的<strong>菜單</strong>，或<strong>活動</strong>模式。當在<strong>活動</strong>中時，輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>settings</span></span></code></pre></div><p>並點擊相應的圖標。</p><p>選擇 <ruby>網絡<rt>Network</rt></ruby> 標籤。</p><p>點擊<strong>設置按鈕</strong>（齒輪）以顯示你的網絡配置文件的參數。</p><p>打開 <ruby>詳情<rt>Details</rt></ruby>標籤，查看你的計算機的 IP 地址。</p><p>進入 <strong>你的客户端的</strong> 終端（你想從它連接到別的計算機），使用 <code>ping</code> 命令找出客户和服務器之間是否有連接。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ping -c 5 192.168.122.225</span></span></code></pre></div><p>檢查該命令的輸出。如果它與下面的例子相似，説明計算機之間的連接存在。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PING 192.168.122.225 (192.168.122.225) 56(84) bytes of data.</span></span>
<span class="line"><span>64 bytes from 192.168.122.225: icmp_seq=1 ttl=64 time=0.383 ms</span></span>
<span class="line"><span>64 bytes from 192.168.122.225: icmp_seq=2 ttl=64 time=0.357 ms</span></span>
<span class="line"><span>64 bytes from 192.168.122.225: icmp_seq=3 ttl=64 time=0.322 ms</span></span>
<span class="line"><span>64 bytes from 192.168.122.225: icmp_seq=4 ttl=64 time=0.371 ms</span></span>
<span class="line"><span>64 bytes from 192.168.122.225: icmp_seq=5 ttl=64 time=0.319 ms</span></span>
<span class="line"><span>--- 192.168.122.225 ping statistics ---</span></span>
<span class="line"><span>5 packets transmitted, 5 received, 0% packet loss, time 4083ms</span></span>
<span class="line"><span>rtt min/avg/max/mdev = 0.319/0.350/0.383/0.025 ms</span></span></code></pre></div><p>如果兩台計算機存在同一個子網中，例如在你的家裏或辦公室，你可能不會遇到任何問題，但當你的服務器沒有<strong>公共 IP 地址</strong>，無法從外部互聯網上看到時，可能會出現問題。除非你是互聯網接入點的唯一管理員，否則你可能需要就你的情況向你的管理員或你的 ISP 諮詢。請注意，將你的計算機暴露在外部互聯網上始終是一個有風險的策略，你<strong>必須充分注意</strong>保護你的計算機免受不必要的訪問。</p><h4 id="安裝-vnc-客户端-remmina" tabindex="-1">安裝 VNC 客户端（Remmina） <a class="header-anchor" href="#安裝-vnc-客户端-remmina" aria-label="Permalink to “安裝 VNC 客户端（Remmina）”">​</a></h4><p>Remmina 是一個圖形化的遠程桌面客户端，你可以使用多種協議連接到遠程服務器，如 VNC、Spice 或 RDP。Remmina 可以從 Fedora 倉庫中獲得，所以你可以用 <code>dnf</code> 命令或 <ruby>軟件中心<rt>Software</rt></ruby> 來安裝它，以你喜歡的方式為準。使用 <code>dnf</code>，下面的命令將安裝該軟件包和幾個依賴項。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install remmina</span></span></code></pre></div><h4 id="連接到服務器" tabindex="-1">連接到服務器 <a class="header-anchor" href="#連接到服務器" aria-label="Permalink to “連接到服務器”">​</a></h4><p>如果服務器和客户端之間有連接，請確保以下情況：</p><ol><li>計算機正在運行。</li><li>Gnome 會話正在運行。</li><li>啓用了屏幕共享的用户已經登錄。</li><li>會話 <strong>沒有被鎖定</strong>，也就是説，用户可以使用該會話。</li></ol><p>然後你可以嘗試從客户端連接到該會話：</p><ol><li>啓動 <strong>Remmina</strong>。</li><li>在地址欄左側的下拉菜單中選擇 <strong>VNC</strong> 協議。</li><li>在地址欄中輸入服務器的IP地址，然後按下 <strong>回車</strong>。 <img src="https://fedoramagazine.org/wp-content/uploads/2022/01/remmina.png" alt="Remmina Window"></li><li>當連接開始時，會打開另一個連接窗口。根據服務器的設置，你可能需要等待，直到服務器用户允許連接，或者你可能需要提供密碼。</li><li>輸入密碼，然後按 <strong>OK</strong>。 <img src="https://fedoramagazine.org/wp-content/uploads/2022/01/remmina_connected_client.png" alt="Remmina Connected to Server"></li><li>按下 <img src="https://fedoramagazine.org/wp-content/uploads/2022/01/resolution.png" alt="Align with resolution button"> 調整連接窗口的大小，使之與服務器的分辨率一致，或者按 <img src="https://fedoramagazine.org/wp-content/uploads/2022/01/full_screen.png" alt="Full Screen Button"> 調整連接窗口的大小，使其覆蓋整個桌面。當處於全屏模式時，注意屏幕上邊緣的白色窄條。那是 Remmina 菜單，當你需要離開全屏模式或改變一些設置時，你可以把鼠標移到它上面。</li></ol><p>當你回到服務器時，你會注意到現在在上欄有一個黃色的圖標，這表明你正在 Gnome 中共享電腦屏幕。如果你不再希望共享屏幕，你可以進入菜單，點擊 <ruby>屏幕正在被共享<rt>Screen is being shared</rt></ruby>，然後再選擇 <ruby>關閉<rt>Turn off</rt></ruby>，立即停止共享屏幕。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2022/01/turn_off_connection.png" alt="Turn off menu item"></p><h4 id="會話鎖定時終止屏幕共享" tabindex="-1">會話鎖定時終止屏幕共享 <a class="header-anchor" href="#會話鎖定時終止屏幕共享" aria-label="Permalink to “會話鎖定時終止屏幕共享”">​</a></h4><p>默認情況下，當會話鎖定時，連接 <ruby>將總是終止<rt>will always terminate</rt></ruby>。在會話被解鎖之前，不能建立新的連接。</p><p>一方面，這聽起來很合理。如果你想和別人分享你的屏幕，你可能不想讓他們在你不在的時候使用你的電腦。另一方面，如果你想從遠程位置控制你自己的電腦，無論是你在另一個房間的牀上，還是你岳母的地方，同樣的方法也不是很有用。有兩個選項可以處理這個問題。你可以完全禁止鎖定屏幕，或者使用支持通過 VNC 連接解鎖會話的 Gnome 擴展。</p><h5 id="禁用屏幕鎖定" tabindex="-1">禁用屏幕鎖定 <a class="header-anchor" href="#禁用屏幕鎖定" aria-label="Permalink to “禁用屏幕鎖定”">​</a></h5><p>要禁用屏幕鎖定：</p><ol><li>打開 <ruby>Gnome 控制中心<rt>Gnome Control Center</rt></ruby>。</li><li>點擊 <ruby>隱私<rt>Privacy</rt></ruby>標籤。</li><li>選擇 <ruby>屏幕鎖定<rt>Screen Lock</rt></ruby> 設置。</li><li>關掉 <ruby>自動屏幕鎖定<rt>Automatic Screen Lock</rt></ruby>。</li></ol><p>現在，會話將永遠不會被鎖定（除非你手動鎖定），所以它能啓動一個 VNC 連接到它。</p><h5 id="使用-gnome-擴展來允許遠程解鎖會話" tabindex="-1">使用 Gnome 擴展來允許遠程解鎖會話 <a class="header-anchor" href="#使用-gnome-擴展來允許遠程解鎖會話" aria-label="Permalink to “使用 Gnome 擴展來允許遠程解鎖會話”">​</a></h5><p>如果你不想關閉鎖定屏幕的功能，或者你想有一個遠程解鎖會話的選項，即使它被鎖定，你將需要安裝一個提供這種功能的擴展，因為這種行為是默認不允許的。</p><p>要安裝該擴展：</p>`,44)),i("ol",null,[i("li",null,[t[1]||(t[1]=n("打開",-1)),t[2]||(t[2]=i("strong",null,"火狐瀏覽器",-1)),t[3]||(t[3]=n("，並打開 ",-1)),r(e,{href:"https://extensions.gnome.org"},{default:s(()=>[...t[0]||(t[0]=[n("Gnome 擴展頁面",-1)])]),_:1}),t[4]||(t[4]=n("。 ",-1)),t[5]||(t[5]=i("img",{src:"https://fedoramagazine.org/wp-content/uploads/2022/01/extensions.png",alt:"Gnome Extensions Page"},null,-1))]),t[6]||(t[6]=a('<li>在頁面的上部，找到一個信息塊，告訴你為火狐安裝 “GNOME Shell integration”。</li><li>點擊 <ruby>點此安裝瀏覽器擴展<rt>Click here to install browser extension</rt></ruby> 來安裝 Firefox 擴展。</li><li>安裝完畢後，注意到 Firefox 的菜單部分有 Gnome 的標誌。</li><li>點擊 Gnome 標誌，回到擴展頁面。</li><li>搜索 “allow locked remote desktop”。</li><li>點擊顯示的項目，進入該擴展的頁面。</li><li>使用右邊的<strong>開/關</strong>按鈕，將擴展<strong>打開</strong>。 <img src="https://fedoramagazine.org/wp-content/uploads/2022/01/switch_on_extension.png" alt="Extension selected"></li>',7))]),t[23]||(t[23]=a('<p>現在，可以在任何時候啓動 VNC 連接。注意，你需要知道會話密碼以解鎖會話。如果你的 VNC 密碼與會話密碼不同，你的會話仍然受到 <em>一點</em> 保護。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>這篇文章介紹了在 Gnome 中實現共享計算機屏幕的方法。它提到了受限（<em>僅瀏覽</em>）訪問和非受限（<em>完全</em>）訪問之間的區別。然而，對於正式任務的遠程訪問，例如管理一個生產服務器，這個解決方案無論如何都不算是一個正確的方法。為什麼？</p><ol><li>服務器將始終保持其<strong>控制模式</strong>。任何在服務器會話中的人都將能夠控制鼠標和鍵盤。</li><li>如果會話被鎖定，從客户端解鎖也會在服務器上解鎖。它也會把顯示器從待機模式中喚醒。任何能看到你的服務器屏幕的人都能看到你此刻正在做什麼。</li><li>VNC 協議本身沒有加密或保護，所以你通過它發送的任何東西都可能被泄露。</li></ol><p>你幾種可以建立一個受保護的 VNC 連接的方法。例如，你可以通過 SSH 協議建立隧道，以提高安全性。然而，這些都超出了本文的範圍。</p><p><strong>免責聲明</strong>：上述工作流程在 Fedora 35 上使用幾個虛擬機工作時沒有問題。如果它對你不起作用，那麼你可能遇到了一個錯誤。請報告它。</p><hr>',7)),i("p",null,[t[8]||(t[8]=n("via: ",-1)),r(e,{href:"https://fedoramagazine.org/sharing-the-computer-screen-in-gnome/"},{default:s(()=>[...t[7]||(t[7]=[n("https://fedoramagazine.org/sharing-the-computer-screen-in-gnome/",-1)])]),_:1})]),i("p",null,[t[13]||(t[13]=n("作者：",-1)),r(e,{href:"https://fedoramagazine.org/author/lruzicka/"},{default:s(()=>[...t[9]||(t[9]=[n("Lukáš Růžička",-1)])]),_:1}),t[14]||(t[14]=n(" 選題：",-1)),r(e,{href:"https://github.com/lujun9972"},{default:s(()=>[...t[10]||(t[10]=[n("lujun9972",-1)])]),_:1}),t[15]||(t[15]=n(" 譯者：",-1)),r(e,{href:"https://github.com/geekpi"},{default:s(()=>[...t[11]||(t[11]=[n("geekpi",-1)])]),_:1}),t[16]||(t[16]=n(" 校對：",-1)),r(e,{href:"https://github.com/wxy"},{default:s(()=>[...t[12]||(t[12]=[n("wxy",-1)])]),_:1})]),i("p",null,[t[19]||(t[19]=n("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[17]||(t[17]=[n("LCTT",-1)])]),_:1}),t[20]||(t[20]=n(" 原創編譯，",-1)),r(e,{href:"https://linux.cn/"},{default:s(()=>[...t[18]||(t[18]=[n("Linux中國",-1)])]),_:1}),t[21]||(t[21]=n(" 榮譽推出",-1))])])}const x=o(m,[["render",d]]);export{C as __pageData,x as default};
